turns.assistant:
One script rewrites every frame's inline colors/fonts onto the tokens, then reviews each.

const { frames, checks } = diazo
const MAP = { '#1a1a1a': 'var(--ink)', '#fafafa': 'var(--paper)', '#3b82f6': 'var(--accent)', /* 22 literal values, ~700 chars */ }
const touched = []
for (const id of ['f1','f2','f3','f4','f5','f6','f7','f8','f9','f10']) {
  const n = await frames.replaceValues(id, MAP)
  touched.push([id, n])
}
const reviews = []
for (const id of ['f1','f2','f3','f4','f5','f6','f7','f8','f9','f10']) reviews.push(await checks.review(id))
return { touched, errors: reviews.flatMap(r => r.findings.filter(f => f.level === 'error')) } /* ~1,600 chars */
